package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Retains the complete original API67 source. The seventh case is pending its
// corrected Salesforce proof and is deliberately outside this six-contract gate.
func TestRunCompressionAdmittedSixProof(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCompressionProof67.cls"), "@IsTest private class GladeCompressionProof67 {\nprivate static String central(Blob archive) {String bytes=EncodingUtil.convertToHex(archive).toLowerCase();Integer offset=bytes.indexOf('504b0102');System.assert(offset>=0,'Expected ZIP central directory');return bytes.substring(offset);}\n@IsTest static void independentStoredBytesAndMetadata() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));Compression.ZipEntry e=r.getEntry('stored.bin');System.assertEquals('stored.bin',e.getName());System.assertEquals('owned stored comment',e.getComment());System.assertEquals(Compression.Method.STORED,e.getMethod());System.assertEquals(6L,e.getCompressedSize());System.assertEquals(6L,e.getUncompressedSize());System.assertEquals(4210012891L,e.getCrc());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),e.getLastModifiedTime());System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.extract('stored.bin')).toLowerCase());System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.extract(e)).toLowerCase()); }\n@IsTest static void independentDeflateAndUnicode() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));Compression.ZipEntry e=r.getEntry('unicodé/雪.txt');System.assertEquals(Compression.Method.DEFLATED,e.getMethod());System.assertEquals(18L,e.getCompressedSize());System.assertEquals(352L,e.getUncompressedSize());System.assertEquals(3277694539L,e.getCrc());System.assertEquals('Héllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\n',r.extract(e).toString()); }\n@IsTest static void independentEmptyAndCaseDistinctNames() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));System.assertEquals(5,r.getEntries().size());System.assertEquals(5,r.getEntriesMap().size());System.assertEquals(true,r.getEntryNames().contains('Case.txt'));System.assertEquals(true,r.getEntryNames().contains('case.txt'));System.assertEquals('UPPER',r.extract('Case.txt').toString());System.assertEquals('lower',r.extract('case.txt').toString());System.assertEquals(0,r.extract('empty').size());System.assertEquals(0L,r.getEntry('empty').getCrc()); }\n@IsTest static void writerStoredOptionChangesArchiveBytes() { Compression.ZipWriter w=new Compression.ZipWriter();w.setMethod(Compression.Method.STORED);w.addEntry('stored.bin',EncodingUtil.convertFromHex('000102ff415a'));Blob zip=w.getArchive();String hex=EncodingUtil.convertToHex(zip).toLowerCase();System.assertEquals('504b0304',hex.substring(0,8));System.assertEquals('0000',hex.substring(16,20));String directory=central(zip);System.assertEquals('0000',directory.substring(20,24));System.assertEquals('dbb2effa',directory.substring(32,40));System.assertEquals('06000000',directory.substring(40,48));System.assertEquals('06000000',directory.substring(48,56)); }\n@IsTest static void writerExplicitEntryMetadataSurvives() { Compression.ZipWriter w=new Compression.ZipWriter();Compression.ZipEntry e=w.addEntry('stored.bin','owned stored comment',Datetime.newInstanceGMT(2024,2,3,4,5,6),Compression.Method.STORED,EncodingUtil.convertFromHex('000102ff415a'));System.assertEquals('000102ff415a',EncodingUtil.convertToHex(e.getContent()).toLowerCase());Compression.ZipReader r=new Compression.ZipReader(w.getArchive());System.assertEquals('owned stored comment',r.getEntry('stored.bin').getComment());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),r.getEntry('stored.bin').getLastModifiedTime());System.assertEquals(Compression.Method.STORED,r.getEntry('stored.bin').getMethod());System.assertEquals(4210012891L,r.getEntry('stored.bin').getCrc()); }\n@IsTest static void compressionLevelChangesPhysicalSize() { Blob data=Blob.valueOf('');Compression.ZipWriter plain=new Compression.ZipWriter();plain.setMethod(Compression.Method.DEFLATED);plain.setLevel(Compression.Level.NO_COMPRESSION);plain.addEntry('owned.txt',data);Compression.ZipWriter best=new Compression.ZipWriter();best.setMethod(Compression.Method.DEFLATED);best.setLevel(Compression.Level.BEST_COMPRESSION);best.addEntry('owned.txt',data);Blob a=plain.getArchive();Blob b=best.getArchive();System.assert(a.size()>b.size(),'NO_COMPRESSION must not compress this repeated payload');System.assertEquals('0800',central(a).substring(20,24));System.assertEquals('0800',central(b).substring(20,24));System.assertEquals('1afb37b7',central(a).substring(32,40));System.assertEquals('1afb37b7',central(b).substring(32,40)); }\n@IsTest static void prototypeCopyHasIndependentMutableState() { Compression.ZipWriter original=new Compression.ZipWriter();Compression.ZipEntry source=original.addEntry('copy.txt','before',Datetime.newInstanceGMT(2024,2,3,4,5,6),Compression.Method.STORED,Blob.valueOf('original'));Compression.ZipWriter destination=new Compression.ZipWriter();Compression.ZipEntry copy=destination.addEntry(source);source.setComment('changed');source.setContent(Blob.valueOf('changed'));source.setLastModifiedTime(Datetime.newInstanceGMT(2025,1,1,0,0,0));System.assertEquals('before',copy.getComment());System.assertEquals('original',copy.getContent().toString());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),copy.getLastModifiedTime());System.assertEquals('original',new Compression.ZipReader(destination.getArchive()).extract('copy.txt').toString());System.assertEquals('changed',source.getContent().toString()); }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCompressionProof67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	index := loadTestIndex(t, root)
	if n := len(Discover(index, Options{})); n != 7 {
		t.Fatalf("original discovery = %d, want7", n)
	}
	run := Run(index, Options{Filter: "GladeCompressionProof67.independentStoredBytesAndMetadata,GladeCompressionProof67.independentDeflateAndUnicode,GladeCompressionProof67.writerStoredOptionChangesArchiveBytes,GladeCompressionProof67.writerExplicitEntryMetadataSurvives,GladeCompressionProof67.compressionLevelChangesPhysicalSize,GladeCompressionProof67.prototypeCopyHasIndependentMutableState"})
	if got := run.Summary(); got.Total != 6 || got.Passed != 6 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("six admitted Compression cases: %s", data)
	}
}

// Native constructor routing must not capture a source-defined class whose name
// happens to match the platform namespace, including an empty passive class.
func TestRunCompressionSourceClassConstructorPrecedence(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "Compression.cls"), `public class Compression {
 public class ZipReader {}
 public class ZipWriter {public String marker(){return 'owned-source';}}
}`)
	writeFile(t, filepath.Join(root, "CompressionShadowTest.cls"), `@IsTest private class CompressionShadowTest {
 @IsTest static void sourceConstructorsRetainPrecedence(){
  Compression.ZipReader reader = new Compression.ZipReader();
  System.assertNotEquals(null,reader);
  Compression.ZipWriter writer = new Compression.ZipWriter();
  System.assertEquals('owned-source',writer.marker());
 }
}`)
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("source constructor precedence: %s", data)
	}
}

// Exact API67 archive, metadata, error and default contracts admitted on Salesforce.
func TestRunCompressionAdmittedErrorsProof(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipContracts67.cls"), "@IsTest private class GladeZipContracts67 {\n@IsTest static void rejectsEmptyBlob(){Boolean caught=false;try{Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Could not load Zip \\nError on ZipFile unknown archive',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void rejectsNotZip(){Boolean caught=false;try{Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode('b3duZWQtbm90LWEtemlw'));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Could not load Zip \\nError on ZipFile unknown archive',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void rejectsTruncated(){Boolean caught=false;try{Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Could not load Zip \\nError on ZipFile unknown archive',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void retainsBadCRCMetadataAndExtractsBytes(){Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));Compression.ZipEntry e=r.getEntry('stored.bin');System.assertEquals(0L,e.getCrc());System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.extract(e)).toLowerCase());}\n@IsTest static void missingReaderEntryDereference(){Boolean caught=false;try{new Compression.ZipReader(EncodingUtil.base64Decode('')).getEntry('missing').getName();}catch(Exception e){caught=true;System.assertEquals('System.NullPointerException',e.getTypeName());System.assertEquals('Attempt to de-reference a null object',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void missingReaderExtraction(){Boolean caught=false;try{new Compression.ZipReader(EncodingUtil.base64Decode('')).extract('missing');}catch(Exception e){caught=true;System.assertEquals('System.NullPointerException',e.getTypeName());System.assertEquals('Attempt to de-reference a null object',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void readerEntryContentIsOwnedBlob(){Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.getEntry('stored.bin').getContent()).toLowerCase());}\n@IsTest static void missingWriterEntryIsNull(){Compression.ZipWriter w=new Compression.ZipWriter();System.assertEquals(null,w.getEntry('missing'));}\n@IsTest static void removeMissingThrowsAndPreservesState(){Compression.ZipWriter w=new Compression.ZipWriter();w.addEntry('keep',Blob.valueOf('keep'));Boolean caught=false;try{w.removeEntry('missing');}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Entry \"missing\" not found',e.getMessage());}System.assertEquals(true,caught);System.assertEquals(new Set<String>{'keep'},w.getEntryNames());System.assertEquals('keep',w.getEntry('keep').getContent().toString());}\n@IsTest static void duplicateExactNameThrowsAfterCaseVariant(){Integer stage=0;Boolean caught=false;try{Compression.ZipWriter w=new Compression.ZipWriter();w.addEntry('A.txt',Blob.valueOf('upper'));stage=1;w.addEntry('a.txt',Blob.valueOf('lower'));stage=2;w.addEntry('A.txt',Blob.valueOf('replacement'));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Duplicate entry \"A.txt\" specified',e.getMessage());}System.assertEquals(true,caught);System.assertEquals(2,stage);}\n@IsTest static void rejectsNullName(){Boolean caught=false;try{Compression.ZipWriter w=new Compression.ZipWriter();w.addEntry((String)null,Blob.valueOf('owned'));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Entry name empty',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void rejectsEmptyName(){Boolean caught=false;try{Compression.ZipWriter w=new Compression.ZipWriter();w.addEntry('',Blob.valueOf('owned'));}catch(Exception e){caught=true;System.assertEquals('compression.ZipException',e.getTypeName());System.assertEquals('Entry name empty',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void nullContentProducesEmptyEntry(){Compression.ZipWriter w=new Compression.ZipWriter();w.addEntry('owned',(Blob)null);String hex=EncodingUtil.convertToHex(w.getArchive()).toLowerCase();Integer offset=hex.indexOf('504b0102');System.assert(offset>=0);String central=hex.substring(offset);System.assertEquals('00000000',central.substring(32,40));System.assertEquals('00000000',central.substring(48,56));System.assertEquals('0500',central.substring(56,60));}\n@IsTest static void rejectsNullMethod(){Boolean caught=false;try{Compression.ZipWriter w=new Compression.ZipWriter();w.setMethod((Compression.Method)null);}catch(Exception e){caught=true;System.assertEquals('System.TypeException',e.getTypeName());System.assertEquals('java.lang.NullPointerException: Cannot invoke \"java.lang.Number.intValue()\" because the return value of \"sun.invoke.util.ValueConversions.primitiveConversion(sun.invoke.util.Wrapper, Object, boolean)\" is null',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void rejectsNullLevel(){Boolean caught=false;try{Compression.ZipWriter w=new Compression.ZipWriter();w.setLevel((Compression.Level)null);}catch(Exception e){caught=true;System.assertEquals('System.TypeException',e.getTypeName());System.assertEquals('java.lang.NullPointerException: Cannot invoke \"java.lang.Number.intValue()\" because the return value of \"sun.invoke.util.ValueConversions.primitiveConversion(sun.invoke.util.Wrapper, Object, boolean)\" is null',e.getMessage());}System.assertEquals(true,caught);}\n@IsTest static void writerDefaultsAndEmptyArchive(){Compression.ZipWriter w=new Compression.ZipWriter();System.assertEquals(Compression.Method.DEFLATED,w.getMethod());System.assertEquals(Compression.Level.BEST_SPEED,w.getLevel());System.assertEquals(0,w.getEntries().size());System.assertEquals(0,w.getEntryNames().size());System.assertEquals('UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA==',EncodingUtil.base64Encode(w.getArchive()));}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipContracts67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 16 || got.Passed != 16 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact16 Compression contracts: %s", data)
	}
}
